func (h *MessageHandler) HandleToolResult(ctx context.Context, loopID string, toolResult agentic.ToolResult) (HandlerResult, error) {
	// Check for cancellation before processing
	if err := ctx.Err(); err != nil {
		return HandlerResult{}, fmt.Errorf("%w: %w", errCancelledBeforeMutation, err)
	}
	originalToolResult := toolResult
	entity, err := h.loopManager.GetLoop(loopID)
	if err != nil {
		return HandlerResult{}, err
	}
	// A terminal loop can apply nothing. Refused BEFORE the result is stored,
	// the pending set touched, a trajectory step added or the timeout arm run,
	// so the refusal is effect-free (#1362 re-review M2, M4). It used to sit
	// behind all of those, reached only when the batch was complete.
	if entity.State.IsTerminal() {
		h.logger.Warn("ignoring tool result for terminal loop",
			slog.String("loop_id", loopID),
			slog.String("execution_id", toolResult.ExecutionID),
			slog.String("state", entity.State.String()))
		return terminalGuardResult(loopID, entity.State), nil
	}
	result := HandlerResult{
		LoopID:            loopID,
		State:             entity.State,
		PendingTools:      h.loopManager.GetPendingTools(loopID),
		PublishedMessages: []PublishedMessage{},
		TrajectorySteps:   []agentic.TrajectoryStep{},
		ContextEvents:     []agentic.ContextEvent{},
	}
	appendTrajectoryObservation(&result, trajectoryObservation{
		LoopID:            loopID,
		Kind:              agentic.TrajectoryKindToolCompleted,
		SourceKind:        agentic.TrajectorySourceToolCall,
		SourceCorrelation: originalToolResult.CallID,
		CausalIteration:   positiveUint32(entity.Iterations),
		CausalPhase:       agentic.TrajectoryPhaseToolResult,
		CausalOrdinal:     h.loopManager.GetToolOrdinal(originalToolResult.ExecutionID),
		ElapsedMS:         h.computeToolDuration(originalToolResult.ExecutionID),
		Status:            toolResultStatus(originalToolResult),
		ToolPreview:       originalToolResult.Name,
		CapabilityPreview: entity.Role,
		ErrorCategory:     toolErrorCategory(originalToolResult),
		Evidence: trajectoryToolCompletionEvidence{
			Result:            originalToolResult,
			DispatchArguments: h.loopManager.GetToolArguments(originalToolResult.ExecutionID),
		},
	})

	// Check for timeout before processing
	if h.loopManager.IsTimedOut(loopID) {
		return h.failTimedOutLoop(loopID, result, "HandleToolResult")
	}

	// Truncate oversized tool results before they enter the context window.
	if h.config.ToolResultMaxBytes > 0 && len(toolResult.Content) > h.config.ToolResultMaxBytes {
		original := len(toolResult.Content)
		toolResult.Content = truncateToolResult(toolResult.Content, h.config.ToolResultMaxBytes)
		h.logger.Warn("tool result truncated",
			slog.String("loop_id", loopID),
			slog.String("tool", toolResult.Name),
			slog.Int("original_bytes", original),
			slog.Int("max_bytes", h.config.ToolResultMaxBytes))
	}

	// Store this tool result for accumulation
	err = h.loopManager.StoreToolResult(loopID, toolResult)
	if err != nil {
		return HandlerResult{}, err
	}

	// Remove from pending tools
	err = h.loopManager.RemovePendingTool(loopID, toolResult.CallID)
	if err != nil {
		return HandlerResult{}, err
	}

	result.PendingTools = h.loopManager.GetPendingTools(loopID)

	// Record trajectory step
	step := h.buildToolTrajectoryStep(toolResult, entity)
	result.TrajectorySteps = append(result.TrajectorySteps, step)

	// Eagerly add the step so active-loop completion mechanics can inspect
	// tool calls and calculate token totals from one in-process snapshot.
	if _, addErr := h.trajectoryManager.addStep(loopID, step); addErr != nil {
		h.logger.Warn("failed to add tool_call trajectory step",
			slog.String("loop_id", loopID),
			slog.String("error", addErr.Error()))
	}

	// Handle approval gating: pause on first approval_required result,
	// absorb sibling results that land afterward.
	if h.checkApprovalGate(loopID, &entity, toolResult, &result) {
		return result, nil
	}

