func (m *LoopManager) IsTimedOut(loopID string) bool {
	m.mu.RLock()
	defer m.mu.RUnlock()

	entity, exists := m.loops[loopID]
	if !exists {
		return false
	}

	// If no timeout set, not timed out
	if entity.TimeoutAt.IsZero() {
		return false
	}

	return time.Now().After(entity.TimeoutAt)
}

