func (e *gateRefusedError) Error() string {
	if e.state == "" {
		return fmt.Sprintf("approval gate refused: loop %s was released", e.loopID)
	}
	return fmt.Sprintf("approval gate refused: loop %s is %s", e.loopID, e.state)
}

